function bs(arr, t, lo, hi) {
  if(lo>hi) return -1;
  let mid = (lo+hi)>>1;
  if(arr[mid]===t) return mid;
  return arr[mid]<t ? bs(arr,t,mid+1,hi) : bs(arr,t,lo,mid-1);
}

